uint hash(uint x, uint seed) {
    const uint m = 0x5bd1e995U;
    uint hash = seed;
    uint k = x;
    k *= m;
    k ^= k >> 24;
    k *= m;
    hash *= m;
    hash ^= k;
    hash ^= hash >> 13;
    hash *= m;
    hash ^= hash >> 15;
    return hash;
}


uint hash(uvec2 x, uint seed){
    const uint m = 0x5bd1e995U;
    uint hash = seed;
    uint k = x.x; 
    k *= m;
    k ^= k >> 24;
    k *= m;
    hash *= m;
    hash ^= k;
    k = x.y; 
    k *= m;
    k ^= k >> 24;
    k *= m;
    hash *= m;
    hash ^= k;
    hash ^= hash >> 13;
    hash *= m;
    hash ^= hash >> 15;
    return hash;
}

vec2 rotate(vec2 uv, float th) {
    return mat2(cos(th), sin(th), -sin(th), cos(th)) * uv;
}

vec2 gradientDirection(uint hash) {

    float mult = mod(float(hash), 10000.0) / 10000.0;
    float v = iTime * mult * 0.4;

    switch (int(hash) & 3) {
    case 0:
        return rotate(vec2(1.0, 1.0), v);
    case 1:
        return rotate(vec2(-1.0, 1.0), v);
    case 2:
        return rotate(vec2(1.0, -1.0), v);
    case 3:
        return rotate(vec2(-1.0, -1.0), v);
    }
}

float interpolate(float value1, float value2, float value3, float value4, vec2 t) {
    return mix(mix(value1, value2, t.x), mix(value3, value4, t.x), t.y);
}

vec2 fade(vec2 t) {
    // 6t^5 - 15t^4 + 10t^3
	return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

float perlinNoise(vec2 position, uint seed) {
    vec2 floorPosition = floor(position);
    vec2 fractPosition = position - floorPosition;
    uvec2 cellCoordinates = uvec2(floorPosition);
    float value1 = dot(gradientDirection(hash(cellCoordinates, seed)), fractPosition);
    float value2 = dot(gradientDirection(hash((cellCoordinates + uvec2(1, 0)), seed)), fractPosition - vec2(1.0, 0.0));
    float value3 = dot(gradientDirection(hash((cellCoordinates + uvec2(0, 1)), seed)), fractPosition - vec2(0.0, 1.0));
    float value4 = dot(gradientDirection(hash((cellCoordinates + uvec2(1, 1)), seed)), fractPosition - vec2(1.0, 1.0));
    return interpolate(value1, value2, value3, value4, fade(fractPosition));
}

float perlinNoise(vec2 position, int frequency, int octaveCount, float persistence, float lacunarity, uint seed) {
    float value = 0.0;
    float amplitude = 1.0;
    float currentFrequency = float(frequency);
    uint currentSeed = seed;
    for (int i = 0; i < octaveCount; i++) {
        currentSeed = hash(currentSeed, 0x0U);
        value += perlinNoise(position * currentFrequency, currentSeed) * amplitude;
        amplitude *= persistence;
        currentFrequency *= lacunarity;
    }
    return value;
}

float triangleWave(float x) {
    return abs(fract(x) * 2.0 - 1.0);
}

float easeInQuint(float x) {
    return 1.0 - pow(1.0 - x, 3.0);
}

vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5); 
    vec3 b = vec3(0.5, 0.5, 0.5); 
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.0, 0.33, 0.67);
    return a + b * cos(6.28318 * (c*t+d));
}

vec3 grayscale(vec3 c) {
    float a = c.x + c.y + c.z;
    return vec3(a / 3.0);
}

vec3 screen(vec3 a, vec3 b) {
    return 1.0 - (1.0 - a) * (1.0 - b);
}

float mask(float x) {
    return 1.0 - 1.0 / (1.0 + exp(-(x - 0.8) * 6.0));
}

vec3 lerp(float t, vec3 a, vec3 b) {
    return t * a + (1.0 - t) * b;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    vec2 position = fragCoord.xy / iResolution.xy;
    position.x *= iResolution.x / iResolution.y;
    uint seed = 0x578437adU;
    float value = perlinNoise(position, 1, 4, 0.1, 2.0, seed);
    float value2 = perlinNoise(position, 1, 6, 0.2, 2.0, seed);
    vec3 c = palette(value2);
    value = (value + 1.0) * 0.5;
    value = easeInQuint(triangleWave(value * 5.0));
    value = (clamp(0.8 / value, 0.0, 1.0));

    vec3 imgC = ((texture(iChannel0, uv).xyz));
    vec3 current = screen(imgC * 0.4, c * value);
    float m = mask(grayscale(imgC).x);
    m = 0.4 / (1.0 - m);
    vec3 newC = lerp(m, current, imgC);

    fragColor = vec4(newC, 1.0);
}

